{
  "summary":"Implement the analyze function to stream JSONL, count malformed lines, and aggregate per-session turns and invalid_output counts.",
  "files":[{
    "path":"scripts/replay_analyzer.py",
    "content":"import json


def analyze(path: str) -> dict:
    malformed_lines = 0
    sessions: dict = {}

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                malformed_lines += 1
                continue

            session_id = obj.get("sessionId")
            if session_id is None:
                malformed_lines += 1
                continue

            if session_id not in sessions:
                sessions[session_id] = {"turns": 0, "invalid_output": 0}

            obj_type = obj.get("type")
            if obj_type == "agent.turn":
                sessions[session_id]["turns"] += 1
            elif obj_type == "error" and obj.get("code") == "invalid_output":
                sessions[session_id]["invalid_output"] += 1

    return {"malformed_lines": malformed_lines, "sessions": sessions}
